const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),a=require('node:assert/strict');const root=path.resolve(__dirname,'..'),out=path.join(root,'qa/career-page-review-20261116');let browser;const server=http.createServer((req,res)=>{const file=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname.replace(/^\/$/,'/index.html'));if(!file.startsWith(root+'/'))return res.end();fs.readFile(file,(e,b)=>{res.statusCode=e?404:200;res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css','.webp':'image/webp','.ttf':'font/ttf'})[path.extname(file)]||'application/octet-stream');res.end(e?'missing':b);});});
(async()=>{const report={scope:'Local isolated Chromium touchscreen slot947, not production or real phone',errors:[],steps:[]};try{await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true,reducedMotion:'reduce'}),p=await context.newPage();p.on('pageerror',e=>report.errors.push(e.message));await p.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});await p.locator('#enterGame').click();await p.evaluate(()=>{slot=947;$('job').value='barista';$('start').click();clearModals();state.housing='family';state.housingCost=500;state.housingLease={key:'family',monthly:500,depositHeld:0,startMonth:0};state.monthlyPayments={month:state.month,housing:500,living:800,premiums:0};state.homeArrival={fromMonth:-1,targetMonth:0,status:'completed'};save();openGame();clearModals();openRoom();});const before=await p.evaluate(()=>JSON.stringify(state));await p.locator('[data-room=work]').click();await p.locator('.career-scene img').evaluate(i=>i.decode());const card=p.locator('.career-paper'),handle=p.locator('.career-scroll-thumb'),scene=p.locator('.career-scene');await p.getByRole('button',{name:'查看本月职业安排',exact:true}).click();await p.locator('.career-event-hero img').evaluate(i=>i.decode());await p.screenshot({path:path.join(out,'local-work-arrangement-390.png')});report.text=await p.locator('.event-active').innerText();report.steps.push('Actual click from room work to confirmed career page, then monthly career arrangement; original random selection in isolated save');report.ok=true;}catch(e){report.ok=false;report.failure=e.stack;process.exitCode=1;}finally{fs.writeFileSync(path.join(out,'local-work-arrangement-report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser?.close();server.close();}})();
